  'This foundational undergraduate History course surveys premodern global history from human origins and early civilizations through cross-cultural networks and transformations around 1500. It provides a world history core while expanding the syllabus with stronger historical method, source analysis, regional balance, environmental context, material culture, trade networks, religions, and a small research capstone.',
  $wh1json${"slug": "world-history-i", "title": "World History I", "description": "This foundational undergraduate History course surveys premodern global history from human origins and early civilizations through cross-cultural networks and transformations around 1500. It provides a world history core while expanding the syllabus with stronger historical method, source analysis, regional balance, environmental context, material culture, trade networks, religions, and a small research capstone.", "topics": [{"id": "72838cec-a9d8-4471-a945-8e835c5b49c3", "type": "topic", "title": "World History as a Field: Sources, Scale, and Comparison", "description": "Students learn how world historians study large-scale patterns without flattening local difference, using evidence, comparison, connection, and chronology.", "children": [{"id": "f93054e8-959d-4039-a0d9-932e08afc9b5", "type": "subtopic", "title": "World history questions", "children": [{"id": "cb06dc98-86db-46d0-acf2-59be1577ca16", "type": "concept", "title": "Comparison, connection, diffusion, exchange, convergence, divergence, and local specificity"}, {"id": "9211af97-778a-4401-a755-071000d01cb4", "type": "concept", "title": "Civilization, empire, network, ecology, migration, religion, technology, and trade as analytical categories"}, {"id": "7e3f527e-b95d-49a8-a269-5685c49e3743", "type": "concept", "title": "Avoiding Eurocentrism, presentism, civilizational ranking, and single-cause explanations"}], "description": "Students learn how to ask questions that connect regions without making them all the same."}, {"id": "1e192453-89a9-4283-a705-3fa059f87f26", "type": "subtopic", "title": "Sources and evidence", "children": [{"id": "7fe7ea8a-e594-4c0e-8a5e-f798a4967476", "type": "concept", "title": "Texts, inscriptions, archaeology, oral traditions, material culture, art, maps, coins, architecture, and environmental data"}, {"id": "70efa013-bbac-4d4b-84ec-de815918d5d0", "type": "concept", "title": "Translation, genre, provenance, patronage, preservation, and archival silence"}, {"id": "bf37c2a2-e66f-42c7-bd3e-e6272b4a2489", "type": "concept", "title": "Reading sources against the grain and comparing evidence types"}], "description": "The point is to understand the uneven evidence base of premodern global history."}, {"id": "3b2a9b12-d6bb-4159-b810-da1a24fb6053", "type": "subtopic", "title": "Historical argument", "children": [{"id": "c3b0dc23-f485-4f91-b8a0-a12c30899788", "type": "concept", "title": "Thesis, context, evidence, causation, chronology, and counterevidence"}, {"id": "c1a6e75b-6e37-4918-b5d6-a7655ce02623", "type": "concept", "title": "Primary versus secondary sources, historiography, citation, and source annotation"}, {"id": "f02f1585-4f34-4d9c-b917-ece2181849d1", "type": "concept", "title": "Scales of analysis from household to city, region, empire, ocean, and world"}], "description": "Students practice using evidence to make claims across time and place."}]}, {"id": "2ded59cc-5226-4481-8958-1db47e745520", "type": "topic", "title": "Human Origins, Migration, Environment, and Foraging Societies", "description": "This module places early human history in environmental, technological, and migratory context before states and cities.", "children": [{"id": "4ab33097-2ca8-4b45-98f0-77395a8d889f", "type": "subtopic", "title": "Human evolution and migration", "children": [{"id": "4ce1f1c8-816f-4aa1-b55b-fe85940377d6", "type": "concept", "title": "Homo sapiens, earlier hominins, Africa, migration routes, adaptation, and genetic/archaeological evidence"}, {"id": "03f5692c-728a-49f9-9c09-82da8d45bf23", "type": "concept", "title": "Foraging, mobility, kinship, cooperation, language, and symbolic culture"}, {"id": "957fa327-d44f-4c7d-82c2-04471afaf440", "type": "concept", "title": "Cave art, tools, burials, ritual, and debates over interpretation"}], "description": "Students place human history inside deep time and movement."}, {"id": "272534a0-f22d-463a-8591-f205abb3d51e", "type": "subtopic", "title": "Environment and subsistence", "children": [{"id": "ee833af7-c2ef-458a-b7b5-63bd798bc124", "type": "concept", "title": "Ice ages, warming periods, coastlines, megafauna, fire, and ecological niches"}, {"id": "6f2778b6-cdba-4c73-97ea-810dcf1d8ba5", "type": "concept", "title": "Hunter-gatherer economies, seasonal rounds, resource management, and exchange"}, {"id": "da1306c2-5869-427c-8b9b-64f1a882f62e", "type": "concept", "title": "Human impact before agriculture and the risks of assuming simplicity"}], "description": "The gist is to see climate and ecology as conditions humans responded to creatively."}, {"id": "f6980d59-88de-46b5-baa7-3aa40e26cd97", "type": "subtopic", "title": "Evidence limits", "children": [{"id": "ebf8e2e6-c057-4b78-86da-c3e42b9b7c15", "type": "concept", "title": "Archaeology, paleoenvironmental evidence, DNA, artifacts, and comparative anthropology"}, {"id": "e3751ef3-4b64-4df5-894b-2f47af3b4880", "type": "concept", "title": "Dating methods, site preservation, sampling bias, and uncertainty"}, {"id": "6352b3b3-f0ed-4d42-8853-53db0670b36d", "type": "concept", "title": "What historians can and cannot responsibly claim"}], "description": "Students learn why early human history requires careful inference."}]}, {"id": "5dff208b-e3f0-4438-aaac-3d323fb5bdfc", "type": "topic", "title": "Agriculture, Pastoralism, and the Origins of Complex Societies", "description": "Students examine how food production, animal domestication, settlement, surplus, and inequality reshaped human communities.", "children": [{"id": "4d26d00d-cda7-4caa-8a7f-5b4b0a38532e", "type": "subtopic", "title": "Agricultural transitions", "children": [{"id": "3a67a521-be7d-4c9e-8952-4306a11faa03", "type": "concept", "title": "Fertile Crescent, China, Mesoamerica, Andes, New Guinea, Africa, and other centers"}, {"id": "09a43306-2191-48aa-97c8-0d0f2dff445e", "type": "concept", "title": "Domestication of plants and animals, sedentism, storage, and population growth"}, {"id": "f805f874-f399-43a2-bb16-b61ee5d2421c", "type": "concept", "title": "Costs and benefits: labor, diet, disease, hierarchy, and vulnerability"}], "description": "Students examine why food production emerged unevenly in different regions."}, {"id": "ef3b0315-4c05-4e06-930f-1bf31868da10", "type": "subtopic", "title": "Pastoralism and mobility", "children": [{"id": "47efdd6d-9146-472c-bfb3-a71be748f5b4", "type": "concept", "title": "Herding, horse cultures, steppe worlds, transhumance, raiding, trade, and ecological adaptation"}, {"id": "3783183e-5a52-48f2-ba6d-bf5c527c5624", "type": "concept", "title": "Pastoral-state relations, military mobility, and exchange with agricultural societies"}, {"id": "b1930000-4a4c-47af-a4fa-8bb9724bf9aa", "type": "concept", "title": "Nomad stereotypes and the problem of sedentary-source bias"}], "description": "The point is to treat mobile societies as complex historical actors."}, {"id": "1ab40ad1-9e80-4a27-8a63-4a2b81e7a6d4", "type": "subtopic", "title": "Complex societies", "children": [{"id": "86cdecbf-6a34-4036-a084-01a8d4668929", "type": "concept", "title": "Villages, towns, cities, specialization, elites, taxation, writing, law, and ritual authority"}, {"id": "28832494-3648-4580-a34d-a679c7800786", "type": "concept", "title": "Gender, labor, slavery, household organization, and status differences"}, {"id": "b48108e5-aeef-41b5-9084-a2db12188862", "type": "concept", "title": "Debates about civilization, inequality, and state formation"}], "description": "Students connect surplus to social, political, and cultural change."}]}, {"id": "7e2ba5ec-9c11-45d2-9866-42a1b14a622d", "type": "topic", "title": "River Valley Civilizations: Mesopotamia, Egypt, Indus, and Early China", "description": "This topic compares early states, writing systems, law, religion, urbanism, and social hierarchy across major riverine societies.", "children": [{"id": "df78cd02-ce27-4edb-9706-9bb3e0023e27", "type": "subtopic", "title": "Mesopotamia and Egypt", "children": [{"id": "1d9d6578-cda9-4533-b2a8-3e3a18956c65", "type": "concept", "title": "Sumer, Akkad, Babylon, Assyria, pharaohs, Nile ecology, irrigation, temples, palaces, and scribes"}, {"id": "21c65869-469d-4fd9-abdf-867b803cfe75", "type": "concept", "title": "Cuneiform, hieroglyphs, law codes, monumental building, priesthood, and kingship"}, {"id": "f4100ded-46fb-46c4-b08d-48f12d0f8454", "type": "concept", "title": "City-states, territorial states, empire, bureaucracy, and divine authority"}], "description": "Students compare two influential early state systems without collapsing them into one model."}, {"id": "9dc4e247-2c91-4d9a-a022-2eca848c3d80", "type": "subtopic", "title": "Indus and early China", "children": [{"id": "1bbbd1b0-85c6-4f1f-b761-7fac181e09f1", "type": "concept", "title": "Harappan urbanism, trade, planning, undeciphered script, and environmental change"}, {"id": "5848c78c-9faa-4639-b0c8-444d9e4b166e", "type": "concept", "title": "Shang and Zhou China, oracle bones, bronze, ancestor ritual, mandate of heaven, and kinship politics"}, {"id": "51fcb335-435e-4bb1-b72e-d6427b534382", "type": "concept", "title": "Urban planning, writing, ritual, legitimacy, and evidence limits"}], "description": "The gist is to widen the early-civilization frame beyond the Near East."}, {"id": "cedfccf8-c438-4bad-ba06-db5e179e134e", "type": "subtopic", "title": "Comparative themes", "children": [{"id": "e8e1d176-8c23-455f-b469-eb70ddcfd88d", "type": "concept", "title": "River systems, agriculture, trade, social hierarchy, gender, warfare, and religious authority"}, {"id": "80d62f65-d2c4-4e46-94a6-eed3d5cba71f", "type": "concept", "title": "Material culture, architecture, writing, law, and administrative technology"}, {"id": "104183b1-999b-4bcc-8534-985d46bae33f", "type": "concept", "title": "Collapse, continuity, environmental stress, invasion, and internal transformation"}], "description": "Students identify patterns and differences across early complex societies."}]}, {"id": "4dc83e27-e458-48d9-aa2c-fc1b8cabf149", "type": "topic", "title": "States, Empires, and Political Authority in the Ancient World", "description": "Students study how states and empires built power through administration, warfare, taxation, legitimacy, and infrastructure.", "children": [{"id": "d8a7abd0-be29-4b33-b0d6-9943051e81c9", "type": "subtopic", "title": "State formation", "children": [{"id": "a59d1761-63a4-4c03-bfcb-d3a9c1604d62", "type": "concept", "title": "Taxation, bureaucracy, law, armies, roads, writing, calendars, census, and monumental display"}, {"id": "e803cd25-8b69-4293-80d5-39e556f3f09c", "type": "concept", "title": "Legitimacy through gods, ancestors, charisma, conquest, moral order, and ideology"}, {"id": "9e31c75c-3f39-40cc-a058-6fac2ad0fd35", "type": "concept", "title": "Local elites, tribute, coercion, consent, and rebellion"}], "description": "Students learn how rulers made authority durable."}, {"id": "2c71d529-1332-49c6-9b11-3ffb1e110aa1", "type": "subtopic", "title": "Imperial comparison", "children": [{"id": "e3e59365-6df1-4ba6-b2e7-c3123c9ebdf6", "type": "concept", "title": "Persian, Mauryan, Qin/Han, Roman, Assyrian, and other imperial systems"}, {"id": "569d8c98-476a-4ca2-b1e7-cd38b454be16", "type": "concept", "title": "Frontiers, provinces, roads, coinage, law, military logistics, and cultural patronage"}, {"id": "d1b669e7-0071-4d70-9944-ca2f7651cf44", "type": "concept", "title": "Imperial integration, diversity, violence, and negotiation"}], "description": "The point is to compare empire as a political form across regions."}, {"id": "ec6b3ff2-bcaa-4e2e-aced-2e351b6dda6c", "type": "subtopic", "title": "People under states", "children": [{"id": "868b5c9c-fc62-4796-bce9-c04f0ed5bc42", "type": "concept", "title": "Peasants, soldiers, slaves, merchants, artisans, women, migrants, and captives"}, {"id": "1dc82a69-207d-40e8-93c4-308434945bdc", "type": "concept", "title": "Taxes, labor obligations, conscription, courts, markets, and religious institutions"}, {"id": "36dfb654-6029-402f-aaaa-3dfe0a694d90", "type": "concept", "title": "Resistance, accommodation, local autonomy, and social mobility"}], "description": "Students ask how ordinary people experienced state power."}]}, {"id": "c72de897-56da-4d64-a36f-b0d3650fc0d9", "type": "topic", "title": "Classical Mediterranean Worlds: Greece, Rome, Persia, and Hellenistic Connections", "description": "This module treats the classical Mediterranean and Near East as connected political, commercial, and cultural worlds.", "children": [{"id": "84bec6f5-7f25-4657-a1b7-43e763bc7014", "type": "subtopic", "title": "Greek worlds", "children": [{"id": "37dd24c1-8756-48aa-87b1-74046076d4cc", "type": "concept", "title": "Polis, colonization, democracy, oligarchy, slavery, gender, war, philosophy, drama, and religion"}, {"id": "808787dd-a503-4424-b506-c596e7c398d4", "type": "concept", "title": "Athens, Sparta, Ionia, colonies, Persian Wars, Peloponnesian War, and Macedon"}, {"id": "1cfda62c-d4a4-417d-826f-c89865498f7b", "type": "concept", "title": "Sources from historians, plays, inscriptions, archaeology, and material culture"}], "description": "Students examine Greek history as diverse and connected, not only Athens."}, {"id": "def72cf4-c1b4-4780-97fd-35f0d8e0473f", "type": "subtopic", "title": "Persia and Hellenistic exchange", "children": [{"id": "0342942f-2c82-4e53-9084-cec1168e3988", "type": "concept", "title": "Achaemenid Empire, satrapies, roads, imperial ideology, and multiethnic governance"}, {"id": "52914fae-7c08-4e68-85b7-a54e4708014e", "type": "concept", "title": "Alexander, Hellenistic kingdoms, Alexandria, Greek language, science, art, and trade"}, {"id": "a7df6bd2-d812-45f5-8d4f-749a1cc19b58", "type": "concept", "title": "Cultural blending, imperial violence, and local continuity"}], "description": "The gist is to connect the Mediterranean to the Near East and Central Asia."}, {"id": "a4651f55-b0a4-4994-b609-c8dd978b8ea2", "type": "subtopic", "title": "Roman transformations", "children": [{"id": "7fab0579-52d8-4eb6-98bb-806cfd96a719", "type": "concept", "title": "Republican institutions, citizenship, patronage, slavery, conquest, civil war, and imperial rule"}, {"id": "0da05516-5feb-456b-88ce-2ebc0b6a47d0", "type": "concept", "title": "Law, roads, cities, armies, trade, religion, and provincial life"}, {"id": "1d2906b8-b602-4968-afa1-c5dfbd4fc9ff", "type": "concept", "title": "Crisis, Christianity, late antiquity, and debates over decline and transformation"}], "description": "Students study Rome as republic, empire, and Mediterranean system."}]}, {"id": "45b2f237-3ccd-47c9-a7f9-f0d60eb45ba4", "type": "topic", "title": "South Asia, Buddhism, Hindu Traditions, and Indian Ocean Worlds", "description": "Students explore South Asian religious, social, political, and commercial histories in regional and oceanic context.", "children": [{"id": "552caf85-e001-43f0-85af-eccb3a92d0c3", "type": "subtopic", "title": "South Asian polities", "children": [{"id": "035c7641-6e06-4db9-8446-9491a22583f8", "type": "concept", "title": "Vedic societies, mahajanapadas, Maurya, Gupta, regional states, and local power"}, {"id": "e01334c9-7ab5-4969-a97a-d1750fdd2869", "type": "concept", "title": "Kingship, caste/jati, land, temples, cities, and patronage"}, {"id": "0d2c54ac-624c-4786-9b95-a5cc0709dacb", "type": "concept", "title": "Arthashastra, inscriptions, epics, archaeology, and travelers' accounts"}], "description": "Students learn the diversity of South Asian political and social formations."}, {"id": "1604bb82-5512-4c0c-9628-93b617c4705b", "type": "subtopic", "title": "Religious traditions", "children": [{"id": "ac47c684-dae8-46ae-8ac0-361d09adf2d2", "type": "concept", "title": "Hindu traditions, Buddhism, Jainism, dharma, karma, ritual, monasticism, and devotion"}, {"id": "1d2231bd-711d-4868-9274-77eb456ef321", "type": "concept", "title": "Ashoka, Buddhist councils, pilgrimage, Sanskrit, Pali, and vernacular traditions"}, {"id": "5193e06f-1e81-49e9-b92e-8bdfc6023f7a", "type": "concept", "title": "Religious change, philosophical debate, political patronage, and social practice"}], "description": "The point is to study religious traditions historically and contextually."}, {"id": "a887bbe3-0bb5-455d-af10-49b9efceeec2", "type": "subtopic", "title": "Indian Ocean connections", "children": [{"id": "4e4db799-5705-4a6c-8f9f-15b0efe62569", "type": "concept", "title": "Monsoons, ports, merchants, diasporas, spices, textiles, Buddhism, Hinduism, and Islam"}, {"id": "b6eeff45-ab90-4498-822d-5179167ef0d0", "type": "concept", "title": "Arabian Sea, Bay of Bengal, Southeast Asia, East Africa, and China connections"}, {"id": "0874ed02-952a-457d-9321-f7a217125680", "type": "concept", "title": "Maritime technology, credit, cultural exchange, and cosmopolitan port cities"}], "description": "Students see South Asia as a hub of movement and exchange."}]}, {"id": "65f877b7-c975-4065-8330-aad7845240d0", "type": "topic", "title": "Ancient and Medieval China, East Asia, and Inner Asian Connections", "description": "This topic studies East Asian statecraft, Confucian culture, Buddhism, trade, technology, and steppe-sedentary relations.", "children": [{"id": "59bdc49f-fcdc-4ee0-9603-1a0f293104e9", "type": "subtopic", "title": "Chinese state traditions", "children": [{"id": "91f7dafe-8e4b-47f3-af5a-13bfbf44a698", "type": "concept", "title": "Shang, Zhou, Qin, Han, Sui, Tang, Song, and Yuan foundations"}, {"id": "ec4d2aad-7ff0-4d90-abc3-8bfd4824c856", "type": "concept", "title": "Mandate of Heaven, bureaucracy, exams, law, Confucianism, Daoism, Legalism, and ancestor ritual"}, {"id": "239df2c2-2567-40e2-835b-4918fb56ab6b", "type": "concept", "title": "Agriculture, canals, cities, taxation, writing, and social hierarchy"}], "description": "Students examine long-running patterns in East Asian statecraft."}, {"id": "db3d3e47-3733-430c-aa4f-65bd46bfa2d2", "type": "subtopic", "title": "Technology and society", "children": [{"id": "0f9cb6ee-9dcf-4290-a171-4b2ea8526fa7", "type": "concept", "title": "Paper, printing, gunpowder, compass, ceramics, metallurgy, silk, and agriculture"}, {"id": "149cdf83-a428-4d76-849b-28bc896ae64f", "type": "concept", "title": "Family, gender, education, urban life, markets, and literati culture"}, {"id": "6970e6cc-5d14-46b8-8abd-379e53d0b8f0", "type": "concept", "title": "Diffusion, adaptation, state support, and commercial change"}], "description": "The gist is to connect invention to institutions and everyday life."}, {"id": "4a5d8505-617c-4c2e-af60-d1b76dc2cb04", "type": "subtopic", "title": "Inner Asian and regional connections", "children": [{"id": "4cc73774-fe7a-4ccc-9f9b-309a78c1d72c", "type": "concept", "title": "Steppe confederations, Xiongnu, Turks, Mongols, Tibet, Korea, Japan, and Vietnam"}, {"id": "ba335bf5-4119-48ad-8d09-449da0bb1fa5", "type": "concept", "title": "Tribute, trade, warfare, diplomacy, Buddhism, writing systems, and migration"}, {"id": "f7ac5ff0-c275-4aef-b8c0-d396ada771f9", "type": "concept", "title": "Sedentary-steppe relations and the limits of dynasty-centered narratives"}], "description": "Students study East Asia through mobility and frontier interaction."}]}, {"id": "c3de312a-486f-4ec0-b0c7-630d2ff462b6", "type": "topic", "title": "Africa Before 1500: States, Trade, Religion, and Oral Traditions", "description": "Students examine African histories through states, cities, ecology, oral traditions, trade, Islam, Christianity, and regional diversity.", "children": [{"id": "f8b42627-61c2-49ae-b2a9-d245a51e281a", "type": "subtopic", "title": "African regional diversity", "children": [{"id": "85b27814-0b98-4c53-b223-c91d68be9ad9", "type": "concept", "title": "Nile Valley, Nubia, Ethiopia, Sahel, savanna, forest zones, Swahili coast, Great Zimbabwe, and Kongo"}, {"id": "2ca73c5e-be35-4b09-98c4-9fc289464b2b", "type": "concept", "title": "Ecology, agriculture, pastoralism, ironworking, cities, kinship, and political authority"}, {"id": "0097c2e9-faf1-4c8e-83d7-4f8d7fa36c39", "type": "concept", "title": "Avoiding myths of isolation and recognizing African innovation"}], "description": "Students learn Africa as many historical regions and societies."}, {"id": "8be0a7e5-5e12-4753-836f-0de7a1ced7e6", "type": "subtopic", "title": "Trade and religion", "children": [{"id": "1ec14172-464f-42a3-9381-ba4079d383d1", "type": "concept", "title": "Trans-Saharan trade, gold, salt, slaves, horses, textiles, and Islamic scholarship"}, {"id": "ba7c2bb9-dcc9-4cdc-97a1-c72ae69d3ec9", "type": "concept", "title": "Ghana, Mali, Songhai, Timbuktu, Mansa Musa, Ethiopia, Swahili city-states, and coastal commerce"}, {"id": "4df95561-7bf5-4a2f-bf7e-25308be95f9a", "type": "concept", "title": "Islam, Christianity, indigenous religions, literacy, and oral tradition"}], "description": "The point is to connect African societies to Saharan, Red Sea, and Indian Ocean worlds."}, {"id": "1a474226-a504-462a-9b32-f2a244f4a435", "type": "subtopic", "title": "Sources for African history", "children": [{"id": "f3d05575-d5d8-4ec3-b6ea-44ff89dc2ab8", "type": "concept", "title": "Oral traditions, archaeology, linguistics, Arabic texts, travelers, art, and environmental evidence"}, {"id": "bdff47e0-697b-444c-95ae-8ab39ca8ebc3", "type": "concept", "title": "Griot traditions, memory, genealogy, praise poetry, and performance"}, {"id": "fc9f5f05-e381-4d34-a979-210ae843f3d5", "type": "concept", "title": "Source criticism, colonial distortions, and African-centered interpretation"}], "description": "Students learn how historians work with oral and material evidence."}]}, {"id": "5429d540-b47c-4e48-9ccf-2b225da32e73", "type": "topic", "title": "Pre-Columbian Americas: Cities, Empires, Environments, and Knowledge", "description": "This module centers American societies before 1500 as complex, diverse, and innovative historical worlds.", "children": [{"id": "1c73b3ad-b3d7-4d18-83ff-232b44b0f75d", "type": "subtopic", "title": "Mesoamerica", "children": [{"id": "9f52632e-36b7-44ea-bef0-9f6c3b767d35", "type": "concept", "title": "Olmec, Maya, Teotihuacan, Toltec, Mexica/Aztec, city-states, tribute, warfare, and ritual"}, {"id": "fecbd8b2-9483-43bb-88d3-0e2272e61556", "type": "concept", "title": "Calendars, writing, mathematics, astronomy, agriculture, chinampas, and urbanism"}, {"id": "2c89a4ba-d8a4-43e3-98c6-d8554515074d", "type": "concept", "title": "Codices, archaeology, inscriptions, and colonial-era sources"}], "description": "Students study complex American societies before European arrival."}, {"id": "a2d497ea-6bd8-4ca1-bc0e-e515d62ad623", "type": "subtopic", "title": "Andes and North America", "children": [{"id": "dde314a4-5e4e-4846-9476-cb74cfc1e0d2", "type": "concept", "title": "Chavin, Moche, Wari, Tiwanaku, Inca, quipu, roads, terrace farming, and state labor"}, {"id": "34ef6cab-d9a2-4bbf-bb10-e3efb13475a9", "type": "concept", "title": "Mississippian societies, Cahokia, Pueblo worlds, mound building, trade, and regional networks"}, {"id": "8f6db317-7b07-428a-8f6f-f11f4feaac41", "type": "concept", "title": "Ecology, altitude, maize, irrigation, storage, and political organization"}], "description": "The gist is to compare different forms of complexity and environmental adaptation."}, {"id": "e7a97417-17f2-4d8a-8126-ee24cda3e201", "type": "subtopic", "title": "Historical interpretation", "children": [{"id": "4bc1b3c6-4751-4afe-88f8-02c5d123ceed", "type": "concept", "title": "Population, disease vulnerability, technology assumptions, and evidence bias"}, {"id": "0ebc6cf3-471f-4d11-8f3e-f10c991df32c", "type": "concept", "title": "Continuity between pre- and post-contact Indigenous histories"}, {"id": "b6b0fcfa-5c2c-4b53-a8ea-84d07da9b531", "type": "concept", "title": "Museums, repatriation, oral tradition, and public memory"}], "description": "Students challenge narratives that erase Indigenous achievement."}]}, {"id": "77d36a9e-5f52-4fe4-8cf3-c5c69515eef5", "type": "topic", "title": "Religions, Philosophies, and Intellectual Traditions Across Afro-Eurasia", "description": "Students compare belief systems and intellectual traditions as historical forces shaping institutions, ethics, politics, and everyday life.", "children": [{"id": "4d222c61-3b08-4a23-bf94-231fdab4c7c7", "type": "subtopic", "title": "Comparative traditions", "children": [{"id": "904d8251-8931-43b6-8f8a-dd8a73d54458", "type": "concept", "title": "Judaism, Christianity, Islam, Hindu traditions, Buddhism, Confucianism, Daoism, Zoroastrianism, and indigenous traditions"}, {"id": "cf8e83dd-ca16-4866-b740-b2cec6a30610", "type": "concept", "title": "Ritual, ethics, scripture, law, pilgrimage, monasticism, sacrifice, and devotion"}, {"id": "3ea11b5e-244b-4578-86c0-a79f79472716", "type": "concept", "title": "Text, practice, institution, community, and state power"}], "description": "Students learn to compare religious traditions without reducing them to checklists."}, {"id": "7959e437-a4b2-4762-933d-c565f801e659", "type": "subtopic", "title": "Knowledge systems", "children": [{"id": "93dc044c-c06f-4864-abef-29984d0b5f09", "type": "concept", "title": "Philosophy, medicine, astronomy, mathematics, law, grammar, theology, and historiography"}, {"id": "9c538820-aa75-4856-9297-79839a1e44a7", "type": "concept", "title": "Greek, Indian, Chinese, Islamic, African, and medieval European knowledge traditions"}, {"id": "e74242ad-91e5-4020-9c23-3daacc6e177f", "type": "concept", "title": "Translation, commentary, debate, patronage, libraries, and schools"}], "description": "The point is to study intellectual traditions as historical institutions."}, {"id": "8499daf3-0caf-46f6-a312-30d3f7375027", "type": "subtopic", "title": "Religion and society", "children": [{"id": "8dfed687-f90e-4fbd-8428-401c9a87eb9a", "type": "concept", "title": "Conversion, missions, reform, orthodoxy, heresy, syncretism, and religious pluralism"}, {"id": "6964743c-fde9-45a9-917d-b797f48a3419", "type": "concept", "title": "Gender roles, family law, education, charity, and social hierarchy"}, {"id": "3ca3f859-6604-408b-8391-502c47f4756b", "type": "concept", "title": "Conflict, coexistence, tolerance, persecution, and boundary-making"}], "description": "Students connect beliefs to politics, gender, economy, and cultural life."}]}, {"id": "9191fac8-d314-4991-a3ed-7f2492703ecc", "type": "topic", "title": "Late Antiquity, Byzantium, Islamic Worlds, and Medieval Europe", "description": "This topic connects the post-classical Mediterranean, Islamic worlds, Byzantium, and medieval Europe through religion, trade, cities, and conflict.", "children": [{"id": "174832a9-e0eb-4a2a-a484-c1c76dc0c739", "type": "subtopic", "title": "Late antiquity and Byzantium", "children": [{"id": "30fc2502-c10b-4ee8-9e25-43b0b95edb2a", "type": "concept", "title": "Roman imperial change, Christianity, Constantinople, Byzantine statecraft, law, art, and theology"}, {"id": "1ea4b1c4-d08b-4f5e-a6da-43f3cfaa2c3e", "type": "concept", "title": "Persian-Byzantine rivalry, Mediterranean trade, plague, and frontier zones"}, {"id": "2e74ec23-f360-4e54-a8f6-fa413f3f57c6", "type": "concept", "title": "Continuity, rupture, and the evidence of manuscripts, coins, buildings, and chronicles"}], "description": "Students see the post-Roman world as transformation rather than simple collapse."}, {"id": "b44a2b0d-7305-4696-94c3-d73e153f0689", "type": "subtopic", "title": "Islamic worlds", "children": [{"id": "ebd748cf-e7e3-4a08-95a5-5fe429f44955", "type": "concept", "title": "Arabia, Muhammad, caliphates, Quran, hadith, law, ulama, cities, trade, and scholarship"}, {"id": "b99fb935-5c08-46c6-9344-a5c227777bc8", "type": "concept", "title": "Umayyad, Abbasid, Fatimid, Seljuk, Mamluk, Ottoman, Safavid, and Mughal connections"}, {"id": "737ac127-8c06-43d3-a65c-7cbbec1cb5f5", "type": "concept", "title": "Science, philosophy, medicine, Sufism, art, architecture, and plural societies"}], "description": "The gist is to place Islamic history at the center of Afro-Eurasian development."}, {"id": "224e4e17-3d5a-46b9-a6fb-dd9f73b29e72", "type": "subtopic", "title": "Medieval Europe", "children": [{"id": "b12463a3-534d-4c13-b66f-04c398eaeea4", "type": "concept", "title": "Feudalism debates, manorialism, towns, church, monarchy, crusades, universities, and guilds"}, {"id": "26b76bc3-c730-46c2-80e2-f2b54b25c860", "type": "concept", "title": "Latin Christendom, Byzantium, Islamic worlds, Jewish communities, and Mediterranean exchange"}, {"id": "f5af208d-1341-421e-87b7-3e3560871c6c", "type": "concept", "title": "Black Death, social change, and Renaissance origins"}], "description": "Students study Europe comparatively and in connection with other regions."}]}, {"id": "761d578c-3f23-44f8-b094-bd37090fd521", "type": "topic", "title": "Cross-Cultural Connections: Silk Roads, Indian Ocean, Sahara, and Mongol Eurasia", "description": "Students study trade, migration, diplomacy, disease, technology, and cultural exchange across major premodern networks.", "children": [{"id": "45f58a9f-347b-4e59-ae2a-2ed949d9b218", "type": "subtopic", "title": "Silk Roads and steppe worlds", "children": [{"id": "e0a4a8d5-5084-4d5e-9cf7-1c19536782ff", "type": "concept", "title": "Caravans, oasis cities, merchants, diplomats, monks, soldiers, and nomads"}, {"id": "43d8337b-38ac-4305-8562-e3cab0ee90d9", "type": "concept", "title": "Silk, horses, spices, paper, religions, art styles, technologies, and political models"}, {"id": "8704cc20-0300-4ad4-9a85-657b800889bd", "type": "concept", "title": "Sogdians, Turks, Uighurs, Mongols, China, Central Asia, Persia, and the Mediterranean"}], "description": "Students learn networks as movement of people, goods, ideas, and disease."}, {"id": "0d13e9b9-9de0-4350-8c38-3734b27333a9", "type": "subtopic", "title": "Indian Ocean and Sahara", "children": [{"id": "88e2eb7b-b2f2-45ca-926f-e662ff6a2e45", "type": "concept", "title": "Monsoon navigation, dhow trade, Swahili coast, South Asia, Southeast Asia, Arabia, and China"}, {"id": "925c94f3-aaa2-4e40-b4ed-3adf3d4fa77c", "type": "concept", "title": "Trans-Saharan caravans, gold, salt, slaves, Islamic scholarship, and Sahelian states"}, {"id": "8d9ff7a9-750e-40d3-97cd-7c194eb02e08", "type": "concept", "title": "Ports, caravan cities, credit, diaspora, language, and cultural hybridity"}], "description": "The point is to compare maritime and overland exchange systems."}, {"id": "523c2939-08ff-4acc-9790-87ad4faabd8a", "type": "subtopic", "title": "Mongol Eurasia", "children": [{"id": "46fc4cf3-26ea-4ebd-9834-5fd0e145b3be", "type": "concept", "title": "Chinggis Khan, Mongol khanates, Yuan China, Ilkhanate, Golden Horde, and Pax Mongolica debates"}, {"id": "e9ea05a9-b222-479b-8be8-bbac3e5d5137", "type": "concept", "title": "Military organization, postal systems, religious tolerance, trade, plague, and diplomatic exchange"}, {"id": "dbb033ba-e01b-4049-b05a-b3f783114047", "type": "concept", "title": "Violence, integration, ecological effects, and global historical consequences"}], "description": "Students examine conquest and connectivity together."}]}, {"id": "74cb616c-1644-45f5-ab56-b14cbc08838a", "type": "topic", "title": "Crisis, Transformation, and Early Globalization, 1300-1500", "description": "This module examines plague, climate, state change, maritime expansion, and the first stages of a more tightly connected world.", "children": [{"id": "0e815646-176c-4e25-8cd7-67879f52f995", "type": "subtopic", "title": "Crisis and recovery", "children": [{"id": "34acea1a-1e14-4c65-9433-8686fd59bc05", "type": "concept", "title": "Black Death, climate stress, famine, war, rebellion, and labor shortages"}, {"id": "e095bdf5-ae33-43e9-b5ed-36f5c8277b19", "type": "concept", "title": "Europe, Middle East, China, Central Asia, and connected disease ecologies"}, {"id": "f6bd241e-61c5-4702-a220-a39027a91265", "type": "concept", "title": "Demographic change, social mobility, state response, and religious interpretation"}], "description": "Students examine the fourteenth century as disruption and transformation."}, {"id": "b9ae6f90-a160-413a-bc30-1d498f82e2c9", "type": "subtopic", "title": "Maritime expansion", "children": [{"id": "040f0167-e895-436a-9381-4e386d9b007c", "type": "concept", "title": "Ming voyages, Portuguese exploration, Atlantic islands, West Africa, Indian Ocean, and Mediterranean commerce"}, {"id": "efe04785-a415-4906-a56d-037ccee368e3", "type": "concept", "title": "Navigation, cartography, ship design, state sponsorship, merchants, and missionizing"}, {"id": "f1969fa5-3eef-460a-964d-45c8ef67f973", "type": "concept", "title": "Trade, violence, diplomacy, and changing geographic imagination"}], "description": "The gist is to connect older networks to new oceanic routes."}, {"id": "7c887557-6abe-4c0f-afa3-6224c2d3d5e0", "type": "subtopic", "title": "Toward a connected world", "children": [{"id": "f5474665-5249-42c1-9e2d-7c877c7d1538", "type": "concept", "title": "Columbian Exchange, Atlantic slavery beginnings, gunpowder empires, printing, and state centralization"}, {"id": "27933fa8-f802-4957-a35b-aa3b9a14ea30", "type": "concept", "title": "Continuity from pre-1500 networks and novelty of post-1500 global integration"}, {"id": "77ae88c2-1822-4a67-955a-157e1b847b51", "type": "concept", "title": "Periodization debates and world-history transition narratives"}], "description": "Students analyze why 1500 is a useful but imperfect endpoint."}]}, {"id": "0e66510a-f4ef-4ce7-ac21-b548335cef30", "type": "topic", "title": "World History Research Capstone: Evidence, Maps, Material Culture, and Historical Argument", "description": "Students synthesize the course through primary-source analysis, comparative argument, and a small research or public-history artifact.", "children": [{"id": "992edff4-1044-400a-98fa-e87ad2346bad", "type": "subtopic", "title": "Project design", "children": [{"id": "0aa35189-a1e6-442a-9e83-15241d3d5f80", "type": "concept", "title": "Question, region, chronology, comparison, connection, source base, and scope"}, {"id": "90852e14-d6c6-49c8-90ee-4fceb7b082e3", "type": "concept", "title": "Primary-source collection, artifact set, map, timeline, or comparative dossier"}, {"id": "e0c0883e-abff-41a0-9422-e8772768f99c", "type": "concept", "title": "Research log, annotated bibliography, and evidence plan"}], "description": "Students turn a broad world-history theme into a feasible question."}, {"id": "a29dc529-7768-4121-a5e0-5136cb98312b", "type": "subtopic", "title": "Historical evidence", "children": [{"id": "b193554b-42e7-4783-a237-94e7da0a15bd", "type": "concept", "title": "Source annotation, context, corroboration, contradiction, and limitation"}, {"id": "474f3559-1b2b-4f6d-b058-cba96b6ce6d5", "type": "concept", "title": "Maps, images, objects, texts, inscriptions, data, and oral traditions"}, {"id": "7d445671-c81f-4823-a496-62d730aefa88", "type": "concept", "title": "Citation, captions, translation notes, and source ethics"}], "description": "The point is to make an argument from sources, not just summarize content."}, {"id": "e18dd78f-bdf0-4914-a8b8-a52baed36e89", "type": "subtopic", "title": "Public communication", "children": [{"id": "8834e728-d885-4e65-9944-28bec54407bf", "type": "concept", "title": "Short research essay, digital exhibit, map story, museum label set, or presentation"}, {"id": "bf7b9598-0c14-4a85-aa74-079f185be083", "type": "concept", "title": "Clear thesis, visual evidence, accessibility, and historical nuance"}, {"id": "20921132-9475-42f1-977f-59972b087d7e", "type": "concept", "title": "Reflection on scale, comparison, connection, and what evidence cannot show"}], "description": "Students translate world history for an audience."}]}], "dbBacked": true}$wh1json$::jsonb,
